#include <new>
#include <cassert>
#include <type_traits>
#include <utility>
void handler() { throw std::bad_alloc{}; }
int main() {
    std::new_handler previous = std::set_new_handler(handler);
    assert(std::get_new_handler() == handler);
    std::set_new_handler(previous);
    auto alignment = std::align_val_t{64};
    void *storage = ::operator new(64, alignment);
    ::operator delete(storage, alignment);
    std::destroying_delete_t tag = std::destroying_delete;
    (void)tag;
}
